import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"越调·霜角新安八景花屏春晓","description":"","frontmatter":{"title":"越调·霜角新安八景花屏春晓","date":"2026-11-18T00:00:00.000Z","seq":66,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"poem_quote":false,"author":"张可久","source_book":"元曲","prev":{"text":"越调·凭阑人众远楼上","link":"/blogs/元曲·张可久/越调·凭阑人众远楼上.html"},"next":{"text":"南吕·骂玉郎带感皇恩采茶歌富山元宵赏灯","link":"/blogs/元曲·张可久/南吕·骂玉郎带感皇恩采茶歌富山元宵赏灯.html"}},"headers":[],"relativePath":"blogs/元曲·张可久/越调·霜角新安八景花屏春晓.md","filePath":"blogs/元曲·张可久/越调·霜角新安八景花屏春晓.md"}'),o={name:"blogs/元曲·张可久/越调·霜角新安八景花屏春晓.md"};function l(n,a,c,m,_,z){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="越调·霜角新安八景花屏春晓" tabindex="-1">越调·霜角新安八景花屏春晓 <a class="header-anchor" href="#越调·霜角新安八景花屏春晓" aria-label="Permalink to &quot;越调·霜角新安八景花屏春晓&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">初日沧凉，海霞摇曙光。</p><p class="poem-stanza">几折好山如画，晴蔼蔼，郁苍苍。</p><p class="poem-stanza">众芳，云景香，道人眠石床。</p><p class="poem-stanza">唤起南华梦蝶，莺啼在，绿垂杨。</p><p class="poem-stanza">练溪晚渡淡烟微隔，几点投林翮。</p><p class="poem-stanza">千古澄江秀句，空感概，有谁索？拍拍，水光白，小舟争过客。</p><p class="poem-stanza">沽酒归来樵叟，相随到，许仙宅。</p><p class="poem-stanza">南山秋色华盖亭亭，向阳松桂荣。</p><p class="poem-stanza">背立夜坛朝斗，直下看，老人星。</p><p class="poem-stanza">地灵，风物清，众峰环翠赢。</p><p class="poem-stanza">千古仙山道气，谁高似，许宣平。</p><p class="poem-stanza">王陵夕照暮蝉声咽，几树白杨叶。</p><p class="poem-stanza">细细看云岚旧隐，遗庙在，表忠烈。</p><p class="poem-stanza">翌结，弓剑冗，苔花碑字灭。</p><p class="poem-stanza">远水残阳西下，今人见，古时月。</p><p class="poem-stanza">水西烟雨沙浅波平，孤舟长日横。</p><p class="poem-stanza">淡墨潇湘八景，谁移向，富山城。</p><p class="poem-stanza">净名，疏磬声，暮归何处僧？明日披云风顶，呼太白，赏新晴。</p><p class="poem-stanza">渔梁送客浪花飞雪，船阁苍云缺。</p><p class="poem-stanza">一片鸬鹚西照，樯燕语，柳丝结。</p><p class="poem-stanza">话别，情哽咽，酒边歌未阕。</p><p class="poem-stanza">他日寄书双鲤，顺流过，钩台月。</p><p class="poem-stanza">黄山雪霁云开洞府，按罢琼妃舞。</p><p class="poem-stanza">三十六峰图画，张素锦，列冰柱。</p><p class="poem-stanza">几缕，翠烟聚，晓妆眉更妩。</p><p class="poem-stanza">一个山头不白，人知是，炼丹处。</p><p class="poem-stanza">紫阳书声楼观飞惊，好山环翠屏。</p><p class="poem-stanza">谁向山中讲授，朱夫子，鲁先生。</p><p class="poem-stanza">短檠，雪屋灯，琅琅终夜声。</p><p class="poem-stanza">传得先儒道妙，百世下，以文鸣。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
